#include "stock_native_bot_human_snapshot.hpp"
#include "stock_native_bot_python.hpp"
#include "stock_native_bot_descriptor.hpp"
#include <Python.h>
namespace p=stock_native_bot_python;
namespace wot::offline_bot_step {bool load_aim_samples(PyObject*descriptor,std::vector<AimSample>&out){return stock_native_bot_descriptor::aimSamples(descriptor,out);}}
PyObject* project(PyObject*,PyObject*args){PyObject*raw,*snapshot,*descriptor;if(!PyArg_ParseTuple(args,"OOO",&raw,&snapshot,&descriptor))return nullptr;stock_native_bot::HumanDescriptor out;if(!stock_native_bot::readHumanProjections(raw,snapshot,descriptor,out))return nullptr;try{auto result=p::list();for(const auto&row:out.projections){const auto&c=row.config;const std::array<double,18> columns{{double(c.team),double(c.slot),c.half_length,c.half_width,c.view_moving,c.view_still,c.view_delay,c.camo_still,c.camo_moving,c.camo_add,c.camo_net_add,c.camo_multiplier,c.camo_net_multiplier,c.camo_shot,c.camo_net_delay,c.radio,c.relay,0.}};auto values=p::tupleNumbers(columns);p::Ref entry(PyTuple_Pack(3,values.get(),row.last_effort?Py_True:Py_False,row.designated?Py_True:Py_False));p::append(result.get(),entry);}return result.release();}catch(const std::exception&e){if(!PyErr_Occurred())PyErr_SetString(PyExc_ValueError,e.what());return nullptr;}}
PyObject* descriptor(PyObject*,PyObject*args){PyObject*raw,*description;if(!PyArg_ParseTuple(args,"OO",&raw,&description))return nullptr;stock_native_bot::HumanDescriptor out;if(!stock_native_bot::readHumanDescriptor(Py_None,raw,description,out))return nullptr;try{auto result=p::dict();p::set(result.get(),"aim_samples",p::integer(std::int64_t(out.aim_samples.size())));p::set(result.get(),"mass",p::number(out.mass));p::set(result.get(),"contact_mass",p::number(out.contact_mass));p::set(result.get(),"minimum",p::numbers(out.body_minimum));p::set(result.get(),"maximum",p::numbers(out.body_maximum));p::set(result.get(),"shape",p::numbers(out.shape));p::set(result.get(),"class_tag",p::text(out.class_tag));p::set(result.get(),"armor",p::number(out.armor));p::set(result.get(),"caps",p::numbers(std::array<double,3>{{*out.spawn_drive_cap,out.contact_drive_forward,out.contact_drive_reverse}}));p::set(result.get(),"pivot",p::numbers(std::array<double,3>{{double(out.pivot_available),double(out.rotation_around_center),out.track_center}}));p::set(result.get(),"hp",p::numbers(std::array<double,2>{{out.vision_maximum.value_or(-1.),out.radio_maximum.value_or(-1.)}}));auto checkpoints=p::list();if(out.template_actor.checkpoints.available)for(const auto&point:out.template_actor.checkpoints.points)p::append(checkpoints.get(),p::numbers(point));p::set(result.get(),"checkpoints",checkpoints);return result.release();}catch(const std::exception&e){if(!PyErr_Occurred())PyErr_SetString(PyExc_ValueError,e.what());return nullptr;}}
PyMethodDef methods[]={{"project",project,METH_VARARGS,nullptr},{"descriptor",descriptor,METH_VARARGS,nullptr},{nullptr,nullptr,0,nullptr}};
PyMODINIT_FUNC inithuman_projection_test(){Py_InitModule("human_projection_test",methods);}
